@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--cyan:#5ce8e7;--cream:#f3f5ef;--muted:#a9b9ba;--line:rgba(222,246,244,.14);--glass:rgba(6,23,29,.68)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#07141b;color:var(--cream);font-family:'DM Sans',sans-serif;touch-action:none}.game-shell{position:relative;width:100%;height:100%;min-height:440px;overflow:hidden;background:#152d37}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,16,22,.58) 0%,transparent 23%,transparent 62%,rgba(4,17,22,.32) 100%),linear-gradient(90deg,rgba(5,15,19,.2),transparent 25%,transparent 76%,rgba(5,15,19,.2));}.topbar{position:absolute;z-index:2;top:0;left:0;right:0;height:78px;padding:0 4.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,rgba(7,20,27,.56),transparent)}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#f5f6ef;font:800 13px 'Barlow Condensed',sans-serif;letter-spacing:2px}.brand-light{font-weight:500;color:#b8c5c3;margin-left:4px}.brand-mark{display:grid;place-items:center;width:27px;height:27px;border:1px solid var(--cyan);color:var(--cyan);font:800 16px 'Barlow Condensed';transform:skew(-10deg)}.race-label{font:600 10px 'DM Sans';letter-spacing:1.75px;color:#d4dfdb}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#60e5cf;box-shadow:0 0 11px #60e5cf;margin-right:8px}.label-divider{margin:0 12px;color:#597075}.icon-button{width:34px;height:34px;border-radius:50%;border:1px solid rgba(255,255,255,.2);background:rgba(5,19,24,.34);color:#e5efeb;font-size:17px;cursor:pointer}.hud{position:absolute;z-index:2;inset:0;pointer-events:none}.glass{background:var(--glass);border:1px solid rgba(230,250,247,.16);backdrop-filter:blur(13px);box-shadow:0 12px 40px rgba(0,0,0,.15)}.speed-card{position:absolute;left:4.2%;top:105px;width:175px;padding:15px 17px 13px;border-radius:4px}.eyebrow{display:block;color:#a8b7b7;font-size:9px;font-weight:700;letter-spacing:1.65px}.eyebrow span{font-size:8px;color:#718687;margin-left:4px}.speed-readout{display:flex;align-items:baseline;gap:7px;margin:3px 0 9px}.speed-readout span{font:700 49px/.95 'Barlow Condensed',sans-serif;letter-spacing:1px}.speed-readout small{font-size:9px;color:#a9b7b5;letter-spacing:1px}.speed-track,.nitro-track{height:3px;background:rgba(255,255,255,.15);overflow:hidden}.speed-track i{height:100%;width:0;display:block;background:var(--cyan);box-shadow:0 0 9px var(--cyan);transition:width .12s}.race-stats{position:absolute;top:105px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:20px;padding:12px 19px;border-radius:4px}.race-stats>div:not(.stat-separator){min-width:60px}.race-stats strong{display:block;margin-top:3px;font:600 21px 'Barlow Condensed';letter-spacing:.5px}.race-stats strong span{font:600 10px 'DM Sans';color:var(--cyan);margin-left:3px}.race-stats strong small{font:600 9px 'DM Sans';color:#9eafae}.stat-separator{height:30px;width:1px;background:var(--line)}.nitro-card{position:absolute;right:4.2%;top:105px;width:160px;padding:13px 15px 10px;border-radius:4px}.nitro-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}.nitro-title span:last-child{font-size:7px;color:#708987;letter-spacing:.6px}.nitro-track{height:5px;border-radius:3px}.nitro-track i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#54b9ef,#61f1dc);box-shadow:0 0 12px #5ce8e7;border-radius:3px;transition:width .12s}.nitro-ready{margin-top:7px;font-size:8px;letter-spacing:1.1px;color:#72e8d8}.leaderboard{position:absolute;right:4.2%;top:180px;width:160px;padding:12px 14px 9px;border-radius:4px}.leader-heading{display:flex;justify-content:space-between;align-items:center}.leader-heading .live-dot{width:5px;height:5px;margin:0}#raceOrder{list-style:none;padding:7px 0 0;margin:0}#raceOrder li{display:flex;align-items:center;padding:5px 0;border-top:1px solid rgba(255,255,255,.06);color:#bdc9c6;font-size:9px;letter-spacing:.3px}#raceOrder li b{font:700 11px 'Barlow Condensed';width:21px;color:#849795}#raceOrder li span{flex:1}#raceOrder li em{font-style:normal;color:#819594;font-size:8px}#raceOrder li.player{color:#69e8df}#raceOrder li.player b{color:#69e8df}.center-panel,.finish-panel{position:absolute;z-index:3;top:50%;left:10.1%;transform:translateY(-42%);width:min(410px,44vw);padding:26px 0 0;transition:opacity .35s,transform .35s}.center-panel h1,.finish-panel h2{margin:17px 0 10px;font:800 clamp(55px,6.7vw,91px)/.79 'Barlow Condensed',sans-serif;letter-spacing:-1.3px}.center-panel h1 em,.finish-panel h2 em{font-style:normal;color:var(--cyan)}.panel-kicker{display:flex;align-items:center;gap:10px;font-size:9px;font-weight:700;letter-spacing:2px;color:#c1ceca}.kicker-line{width:25px;height:1px;background:var(--cyan)}.panel-copy{max-width:330px;margin:17px 0 22px;color:#c3ceca;font-size:12px;line-height:1.75}.event-details{display:flex;gap:23px;margin-bottom:22px}.event-details>div{display:grid;gap:5px}.event-details strong{font:600 14px 'Barlow Condensed';letter-spacing:.3px}.primary-button{display:flex;align-items:center;justify-content:space-between;width:247px;height:49px;padding:0 17px;border:0;border-radius:2px;background:var(--cyan);color:#061a20;font:800 10px 'DM Sans';letter-spacing:1.35px;cursor:pointer;transition:transform .2s,background .2s;box-shadow:0 5px 25px rgba(92,232,231,.18)}.primary-button:hover{transform:translateY(-2px);background:#8ff2e9}.primary-button b{font-size:17px}.controls-hint{margin-top:16px;display:flex;align-items:center;gap:6px;color:#c5d0ca;font-size:8px;letter-spacing:.8px}.controls-hint>span{display:inline-grid;place-items:center;height:18px;min-width:19px;padding:0 4px;border:1px solid rgba(244,255,249,.4);border-radius:3px;color:#f2f5ee;font-size:8px}.controls-hint i{width:5px}.center-panel.hidden,.finish-panel.hidden{opacity:0;pointer-events:none;transform:translateY(-38%)}.finish-panel{padding-top:0}.finish-score{display:grid;grid-template-columns:1fr 1fr;gap:5px 25px;width:260px;margin:21px 0}.finish-score strong{font:700 25px 'Barlow Condensed'}.toast{position:absolute;z-index:3;top:34%;left:50%;transform:translate(-50%,-50%);font:800 19px 'Barlow Condensed';letter-spacing:3px;color:#fff;text-shadow:0 0 20px #5ce8e7;opacity:0;transition:opacity .2s;pointer-events:none}.toast.show{opacity:1}.bottom-bar{position:absolute;z-index:2;bottom:0;left:0;right:0;height:37px;padding:0 4.2%;display:flex;align-items:center;justify-content:space-between;color:rgba(217,233,227,.56);font-size:8px;letter-spacing:1.2px}.bottom-bar i{font-style:normal;font-size:7px}.footer-center{color:rgba(217,233,227,.44)}.mobile-controls{display:none}
@media(max-width:760px){.topbar{height:60px;padding:0 5%}.race-label{font-size:8px;letter-spacing:1px}.label-divider{margin:0 5px}.speed-card{left:5%;top:76px;width:120px;padding:10px 12px}.speed-readout span{font-size:38px}.race-stats{top:auto;bottom:119px;left:50%;gap:11px;padding:8px 12px}.race-stats>div:not(.stat-separator){min-width:46px}.race-stats strong{font-size:17px}.race-stats .eyebrow{font-size:7px}.stat-separator{height:25px}.nitro-card{right:5%;top:76px;width:120px;padding:10px 11px}.nitro-title{margin-bottom:7px}.leaderboard{right:5%;top:139px;width:120px;padding:9px 10px 6px}.leaderboard li{padding:4px 0!important}.center-panel,.finish-panel{top:48%;left:8%;width:84%;padding-top:0;transform:translateY(-50%)}.center-panel h1,.finish-panel h2{font-size:clamp(54px,13vw,81px);margin:13px 0 7px}.panel-copy{font-size:11px;margin:10px 0 14px;max-width:285px}.event-details{gap:16px;margin-bottom:14px}.event-details strong{font-size:12px}.primary-button{height:44px;width:220px}.controls-hint{display:none}.bottom-bar{height:23px;padding:0 5%;font-size:6px}.footer-center{display:none}.mobile-controls{display:flex;position:absolute;z-index:4;bottom:32px;left:5%;right:5%;height:73px;justify-content:space-between;align-items:flex-end;pointer-events:none}.steer-controls,.pedal-controls{display:flex;gap:8px;align-items:flex-end}.control-button{pointer-events:auto;touch-action:none;user-select:none;-webkit-user-select:none;border:1px solid rgba(232,255,250,.32);background:rgba(7,23,28,.57);backdrop-filter:blur(8px);color:#f4f8f2;cursor:pointer}.steer{width:53px;height:53px;border-radius:50%;font:400 36px/.5 'Barlow Condensed';color:#d8e9e3}.pedal-controls{gap:6px}.brake,.boost{width:51px;height:39px;border-radius:3px;font:700 7px 'DM Sans';letter-spacing:.7px;color:#d3deda}.boost{color:#69ebe1;border-color:rgba(105,235,225,.55)}.boost span{font-size:12px;margin-right:3px}.accelerate{width:61px;height:58px;border-radius:50%;background:rgba(86,222,210,.23);border-color:#65e8dc;font:800 10px 'DM Sans';color:#8af0e6}.accelerate b{font-size:13px}.event-details .eyebrow{font-size:8px}.finish-score{margin:14px 0}.vignette{background:linear-gradient(180deg,rgba(5,16,22,.45),transparent 25%,transparent 58%,rgba(4,17,22,.43))}}
@media(max-height:600px) and (min-width:761px){.topbar{height:58px}.speed-card,.race-stats,.nitro-card{top:75px}.leaderboard{top:148px}.center-panel{top:53%;transform:translateY(-46%) scale(.86);transform-origin:left center}.center-panel.hidden{transform:translateY(-42%) scale(.86)}.bottom-bar{height:26px}}
